[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path ([IO.Path]::GetTempPath()) ('intake-neg-'+[guid]::NewGuid().ToString('N'));try{& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\New-SyntheticFileIntake.ps1') -Destination $tmp|Out-Null;$r=Get-Content (Join-Path $tmp 'register\INT-SYN-001.json') -Raw|ConvertFrom-Json;$r.original_path='../secret.txt';$r|ConvertTo-Json|Set-Content (Join-Path $tmp 'register\INT-SYN-001.json');& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Test-SyntheticFileIntake.ps1') -Path $tmp|Out-Null;if($LASTEXITCODE -eq 0){throw 'INTAKE_TRAVERSAL_ACCEPTED'};Write-Host 'PASS: Intake traversal negative gate.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
